/// The error envelope, identical to the HTTP one. See docs/architecture/shared/04-errors-and-http.md.
class ErrorPayload {
  const ErrorPayload({
    required this.code,
    required this.messageKey,
    this.params,
    required this.traceId,
    this.httpEquivalent,
    this.details,
  });

  /// Reads a decoded JSON map. Unknown keys are ignored, never rejected.
  factory ErrorPayload.fromJson(Map<String, Object?> json) => ErrorPayload(
        code: json['code']! as String,
        messageKey: json['messageKey']! as String,
        params: json['params'] as Map<String, Object?>?,
        traceId: json['traceId']! as String,
        httpEquivalent: json['httpEquivalent'] as int?,
        details: json['details'] == null ? null : (json['details']! as List<Object?>).map((item) => ErrorPayloadDetailsItem.fromJson(item! as Map<String, Object?>)).toList(growable: false),
      );

  /// Stable, for client logic. Changing one is a breaking change.
  final String code;

  /// For display. The client translates it — the server never sends prose.
  final String messageKey;

  /// Interpolation values for the message key.
  final Map<String, Object?>? params;

  /// Lets a user report the problem and someone find it in the log.
  final String traceId;

  /// The status this error would carry over HTTP. A WebSocket frame has no status line, and the mapping in docs/architecture/shared/04-errors-and-http.md holds on both transports.
  final int? httpEquivalent;

  /// Validation only: every invalid field, not just the first.
  final List<ErrorPayloadDetailsItem>? details;

  /// A JSON map with the absent optional fields left out.
  Map<String, Object?> toJson() {
    final Map<String, Object?> json = <String, Object?>{
      'code': code,
      'messageKey': messageKey,
      'traceId': traceId,
    };

    if (params != null) {
      json['params'] = params;
    }

    if (httpEquivalent != null) {
      json['httpEquivalent'] = httpEquivalent;
    }

    if (details != null) {
      json['details'] = details?.map((item) => item.toJson()).toList(growable: false);
    }

    return json;
  }
}

