/// The answer to `permission.requested`, carrying its `id` in `correlationId`. Resolving the same `requestId` twice is a silent ack and **one** execution, never an error and never a double run — several clients watch one session, and a client may resend after reconnecting.
class PermissionResolvePayload {
  const PermissionResolvePayload({
    required this.requestId,
    required this.decision,
    this.scope,
    this.reach,
    this.reason,
    this.answers,
  });

  /// Reads a decoded JSON map. Unknown keys are ignored, never rejected.
  factory PermissionResolvePayload.fromJson(Map<String, Object?> json) => PermissionResolvePayload(
        requestId: json['requestId']! as String,
        decision: json['decision']! as String,
        scope: json['scope'] as String?,
        reach: json['reach'] as String?,
        reason: json['reason'] as String?,
        answers: json['answers'] == null ? null : (json['answers']! as List<Object?>).map((item) => QuestionAnswer.fromJson(item! as Map<String, Object?>)).toList(growable: false),
      );

  /// The request being answered. Idempotency keys on it, so resending after a reconnect costs nothing.
  final String requestId;

  /// Yes or no. There is no third value: silence is handled by the deadline, and it denies.
  final String decision;

  /// How far the decision reaches. Absent means `once`. `session` leaves rules that die with the session; `project` and `always` persist rules — the patterns of the chosen `reach`, with the configured default lifetime — that answer future requests without asking and are revoked through `DELETE /permission-rules/:ruleId`. A scope with no pattern for the chosen reach is `INVALID_INPUT`.
  final String? scope;

  /// Which of the request's `reaches` the rules left by `session`, `project` or `always` take. Absent means `exact`. A reach the request did not offer is `INVALID_INPUT`, and the request stays open. Ignored for `once`.
  final String? reach;

  /// Why it was refused. Required whenever `decision` is `deny` — the schema carries the condition, so no end has to remember it.
  final String? reason;

  /// The answers to a question (`interaction` on the request), one per question, and required for an `allow` of one — a rule the schema cannot carry, because this payload does not say what was asked: the backend checks it against the questions it published, and refuses with `PERMISSION_ANSWERS_INVALID` (the request stays open). Never on a `deny`, and never on a request that is not a question. `scope` and `reach` are ignored on a question: it is `once`.
  final List<QuestionAnswer>? answers;

  /// A JSON map with the absent optional fields left out.
  Map<String, Object?> toJson() {
    final Map<String, Object?> json = <String, Object?>{
      'requestId': requestId,
      'decision': decision,
    };

    if (scope != null) {
      json['scope'] = scope;
    }

    if (reach != null) {
      json['reach'] = reach;
    }

    if (reason != null) {
      json['reason'] = reason;
    }

    if (answers != null) {
      json['answers'] = answers?.map((item) => item.toJson()).toList(growable: false);
    }

    return json;
  }
}

/// Whether [json] satisfies the conditional requirements of [PermissionResolvePayload].
///
/// `reason` is also required when `decision`
/// is `deny` — the reason goes into the audit trail and back to Claude as a message; a refusal nobody can account for is a refusal nobody can learn from.
bool permissionResolvePayloadConditionalsHold(Map<String, Object?> json) {
  if (json['decision'] == 'deny' && json['reason'] is! String) {
    return false;
  }

  return true;
}

/// Whether [json] keeps within the bounds the schema gives [PermissionResolvePayload].
bool permissionResolvePayloadLimitsHold(Map<String, Object?> json) {
  if (json['answers'] is List<Object?> && (json['answers']! as List<Object?>).length > 4) {
    return false;
  }

  return true;
}

